package fraymus.workspace;

import org.json.*;
import java.awt.image.BufferedImage;
import javax.imageio.*;
import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;

/** Durable, source-qualified browser perception. Pixel estimates and page labels retain distinct authority. */
public final class PerceptionStore implements AutoCloseable {
    static final String PROCEDURE="browser-perception-v1";
    private final Path root,file;private final LinkedHashMap<String,JSONObject> frames=new LinkedHashMap<>(),runs=new LinkedHashMap<>(),lessons=new LinkedHashMap<>();
    private final TrackingLab trackingLab;
    public TrackingLab lab(){return trackingLab;}
    private final Map<String,ImageTracker> trackers=new LinkedHashMap<>();private final VisionDetector detector=new VisionDetector();private final ExecutorService worker=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"local-vision-detector");t.setDaemon(true);return t;});private String active="";private boolean closed;
    public PerceptionStore(Path project) throws Exception {trackingLab=new TrackingLab(project);root=project.resolve("perception");file=root.resolve("state.json");if(Files.exists(file)){var data=new JSONObject(Files.readString(file));load(data,"frames",frames);load(data,"runs",runs);load(data,"lessons",lessons);for(var r:runs.values())if(Set.of("detecting","tracking").contains(r.getString("status")))r.put("status","interrupted").put("reason","Process ended; explicitly rebind the browser target and resume");persist();}}
    private static void load(JSONObject data,String key,Map<String,JSONObject> map){for(Object raw:data.getJSONArray(key)){var o=(JSONObject)raw;map.put(o.getString("id"),o);}}
    private static JSONObject copy(JSONObject o){return new JSONObject(o.toString());}
    private synchronized void persist() throws Exception {Files.createDirectories(root);var temp=root.resolve("state.pending.json");Files.writeString(temp,new JSONObject().put("version",1).put("frames",new JSONArray(frames.values())).put("runs",new JSONArray(runs.values())).put("lessons",new JSONArray(lessons.values())).toString());try{Files.move(temp,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING);}}
    static String hash(byte[] data) throws Exception {return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));}
    static String label(String text){if(!text.matches("[a-z][a-z0-9 -]{0,39}"))throw new IllegalArgumentException("Use a short lowercase object category, for example person or cup");return switch(text){case "people","human","humans"->"person";case "cups","mug","mugs"->"cup";default->text;};}
    static BufferedImage decode(byte[] bytes) throws Exception {
        if(bytes.length>1_000_000)throw new IllegalArgumentException("Captured PNG exceeds 1 MB");try(var input=ImageIO.createImageInputStream(new ByteArrayInputStream(bytes))){var readers=ImageIO.getImageReaders(input);if(!readers.hasNext())throw new IllegalArgumentException("Captured image is not supported");var reader=readers.next();try{reader.setInput(input);if(!reader.getFormatName().equalsIgnoreCase("png"))throw new IllegalArgumentException("PNG capture required");int w=reader.getWidth(0),h=reader.getHeight(0);if(w<24||h<24||w>1024||h>1024||w*(long)h>786432)throw new IllegalArgumentException("Capture dimensions exceed the bounded image domain");return reader.read(0);}finally{reader.dispose();}}
    }
    static JSONObject source(JSONObject source){
        SpatialScene.keys(source,"pageId","ref","kind","label","url","signature","crop","scrollX","scrollY","capturedAt","width","height");UUID.fromString(source.getString("pageId"));if(!source.getString("ref").matches("[0-9]{1,6}"))throw new IllegalArgumentException("Invalid browser target reference");if(!Set.of("img","canvas","video","iframe","element","viewport").contains(source.getString("kind")))throw new IllegalArgumentException("Invalid browser source kind");if(!source.getString("signature").matches("[a-f0-9]{64}"))throw new IllegalArgumentException("Browser source signature required");var url=java.net.URI.create(source.getString("url"));if(!Set.of("http","https").contains(url.getScheme())||url.getHost()==null||url.getUserInfo()!=null)throw new IllegalArgumentException("A real HTTP browser source is required");if(source.getString("label").length()>180)throw new IllegalArgumentException("Source label too long");
        var crop=source.getJSONObject("crop");SpatialScene.keys(crop,"x","y","width","height");for(String k:List.of("x","y"))SpatialScene.number(crop,k,0,10000);for(String k:List.of("width","height"))SpatialScene.number(crop,k,24,4096);SpatialScene.number(source,"scrollX",0,1000000);SpatialScene.number(source,"scrollY",0,1000000);SpatialScene.number(source,"width",24,1024);SpatialScene.number(source,"height",24,1024);SpatialScene.number(source,"capturedAt",0,1e15);return source;
    }
    public synchronized JSONObject frame(JSONObject packet) throws Exception {
        SpatialScene.keys(packet,"id","source","png");String id=packet.getString("id");UUID.fromString(id);var source=source(packet.getJSONObject("source"));byte[] bytes=Base64.getDecoder().decode(packet.getString("png"));var image=decode(bytes);if(image.getWidth()!=source.getInt("width")||image.getHeight()!=source.getInt("height"))throw new IllegalArgumentException("PNG dimensions differ from browser capture metadata");String sha=hash(bytes);var prior=frames.get(id);if(prior!=null){if(!sha.equals(prior.getString("sha256"))||!prior.getJSONObject("source").similar(source))throw new IllegalStateException("Captured frame identity already has another source");return copy(prior);}long total=0;for(var f:frames.values())total+=f.getLong("bytes");if(frames.size()>=512||total+bytes.length>128_000_000)throw new IllegalStateException("Private perception capture budget reached (512 frames / 128 MB)");
        Files.createDirectories(root.resolve("frames"));var target=root.resolve("frames").resolve(id+".png");Files.write(target,bytes,StandardOpenOption.CREATE_NEW);var f=new JSONObject().put("id",id).put("sha256",sha).put("bytes",bytes.length).put("source",copy(source)).put("recordedAt",Instant.now().toString());frames.put(id,f);persist();return copy(f);
    }
    public synchronized JSONObject frame(String id){UUID.fromString(id);var f=frames.get(id);if(f==null)throw new IllegalArgumentException("Unknown captured frame");return copy(f);}
    byte[] bytes(String id) throws Exception {var f=frame(id);byte[] bytes=Files.readAllBytes(root.resolve("frames").resolve(id+".png"));if(!hash(bytes).equals(f.getString("sha256")))throw new IllegalStateException("Captured image integrity changed");return bytes;}
    public String png(String id) throws Exception {return Base64.getEncoder().encodeToString(bytes(id));}
    static JSONObject binding(JSONObject f){var s=f.getJSONObject("source");return new JSONObject().put("pageId",s.getString("pageId")).put("ref",s.getString("ref")).put("kind",s.getString("kind")).put("url",s.getString("url")).put("signature",s.getString("signature"));}
    public synchronized JSONArray lessons(){var out=new JSONArray();for(var l:lessons.values())out.put(copy(l));return out;}
    public synchronized JSONObject lesson(String id){UUID.fromString(id);var l=lessons.get(id);if(l==null)throw new IllegalArgumentException("Unknown taught appearance");return copy(l);}
    public synchronized JSONObject teach(JSONObject input) throws Exception {
        SpatialScene.keys(input,"frameId","box","label","name");String name=input.getString("name");if(!name.matches("[a-z][a-z0-9-]{2,55}"))throw new IllegalArgumentException("Teaching name needs 3..56 lowercase characters");int version=1;for(var l:lessons.values())if(l.getString("name").equals(name))version=Math.max(version,l.getInt("version")+1);if(version>8||lessons.size()>=32)throw new IllegalStateException("Taught appearance history limit reached");var f=frame(input.getString("frameId"));var image=decode(bytes(f.getString("id")));String category=label(input.getString("label"));var box=PixelTracker.Box.from(input.getJSONArray("box"));var tracker=new PixelTracker("teaching",category,image,box,false);var l=tracker.lesson().put("id",UUID.randomUUID().toString()).put("name",name).put("version",version).put("label",category).put("frameId",f.getString("id")).put("frameSha256",f.getString("sha256")).put("source",binding(f)).put("authority","user-drawn appearance example, not independently verified semantics").put("createdAt",Instant.now().toString());lessons.put(l.getString("id"),l);persist();return copy(l);
    }
    public synchronized boolean busy(){return !active.isEmpty();}
    public synchronized boolean hasRun(String id){return runs.containsKey(id);}
    public synchronized JSONObject run(String id){UUID.fromString(id);var r=runs.get(id);if(r==null)throw new IllegalArgumentException("Unknown perception run");return copy(r);}
    public synchronized JSONObject state(){var summaries=new JSONArray();for(var r:runs.values())summaries.put(view(r));return new JSONObject().put("runs",summaries).put("lessons",lessons()).put("active",active);}
    public static JSONObject view(JSONObject r){var out=new JSONObject();for(String key:List.of("id","goalId","attempt","status","reason","mode","label","model","lessonId","binding","initialFrameId","lastSequence","latest","metrics","detection","seconds","trackingStartedAt","trackerProfile","trackerCodeSha256"))if(r.has(key))out.put(key,r.get(key));return out;}
    public synchronized JSONObject start(String id,String goalId,int attempt,String frameId,String mode,String target,String model,String lessonId,double seconds) throws Exception {return start(id,goalId,attempt,frameId,mode,target,model,lessonId,seconds,trackingLab.activeProfile());}
    public synchronized JSONObject start(String id,String goalId,int attempt,String frameId,String mode,String target,String model,String lessonId,double seconds,String profile) throws Exception {
        String codeHash=TrackerIdentity.hash(profile);
        if(runs.containsKey(id)){var r=runs.get(id);if(!r.getString("goalId").equals(goalId)||r.getInt("attempt")!=attempt||!r.getString("initialFrameId").equals(frameId))throw new IllegalStateException("Foreign perception effect identity");return view(r);}if(closed||busy())throw new IllegalStateException("One perception task is active");if(runs.size()>=32)throw new IllegalStateException("Perception run history limit reached (32)");if(!Set.of("vision","appearance","dom").contains(mode))throw new IllegalArgumentException("Choose vision, taught appearance or DOM tracking");label(target);RampDefinition.range(seconds,2,30,"tracking seconds");var f=frame(frameId);if(mode.equals("appearance")&&!lesson(lessonId).getString("label").equals(target))throw new IllegalArgumentException("Taught appearance category differs from the requested category");
        var r=new JSONObject().put("id",id).put("goalId",goalId).put("attempt",attempt).put("mode",mode).put("label",target).put("model",model).put("lessonId",lessonId).put("initialFrameId",frameId).put("binding",binding(f)).put("seconds",seconds).put("trackerProfile",profile).put("trackerCodeSha256",codeHash).put("status","detecting").put("lastSequence",0).put("samples",new JSONArray()).put("createdAt",Instant.now().toString());runs.put(id,r);active=id;trackers.clear();persist();worker.submit(()->detect(id));return view(r);
    }
    private JSONObject taughtMemory(BufferedImage image,String category){var found=new JSONArray();var evidence=new JSONArray();var latest=new LinkedHashMap<String,JSONObject>();synchronized(this){for(var l:lessons.values())if(l.getString("label").equals(category)&&(!latest.containsKey(l.getString("name"))||latest.get(l.getString("name")).getInt("version")<l.getInt("version")))latest.put(l.getString("name"),copy(l));}for(var l:latest.values()){var tracker=new PixelTracker("memory",category,PixelTracker.learned(l),PixelTracker.Box.from(l.getJSONArray("box")),false);var match=tracker.match(PixelTracker.working(image),true);if(match.score()<.9||match.anchorScore()<.8)continue;boolean duplicate=false;for(Object raw:found)if(PixelTracker.iou(PixelTracker.Box.from(((JSONObject)raw).getJSONArray("box")),match.box())>.7)duplicate=true;if(!duplicate&&found.length()<6){found.put(new JSONObject().put("label",category).put("box",match.box().json()));evidence.put(new JSONObject().put("id",l.getString("id")).put("name",l.getString("name")).put("version",l.getInt("version")).put("frameSha256",l.getString("frameSha256")).put("matchScore",match.score()));}}return new JSONObject().put("objects",found).put("memoryUsed",!found.isEmpty()).put("taughtExamples",evidence).put("authority","explicit user-taught appearance transferred to current pixels; no model weight training, general category guarantee or personal identity");}
    private void detect(String id){try{
        var r=run(id);var f=frame(r.getString("initialFrameId"));var image=decode(bytes(f.getString("id")));JSONObject result;var objects=new JSONArray();String mode=r.getString("mode");
        var remembered=mode.equals("vision")?taughtMemory(image,r.getString("label")):null;
        if(remembered!=null&&!remembered.getJSONArray("objects").isEmpty()){result=remembered;objects=result.getJSONArray("objects");}
        else if(mode.equals("vision")){var proposals=PixelRegions.propose(image);var regions=new JSONArray();for(var region:proposals){synchronized(this){if(!runs.get(id).getString("status").equals("detecting"))throw new InterruptedException("Perception detection cancelled");}var crop=image.getSubimage(region.x,region.y,region.width,region.height);double enlarge=Math.max(1,512.0/Math.max(crop.getWidth(),crop.getHeight()));var inputImage=new BufferedImage((int)Math.round(crop.getWidth()*enlarge),(int)Math.round(crop.getHeight()*enlarge),BufferedImage.TYPE_INT_RGB);var graphics=inputImage.createGraphics();graphics.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION,java.awt.RenderingHints.VALUE_INTERPOLATION_BICUBIC);graphics.drawImage(crop,0,0,inputImage.getWidth(),inputImage.getHeight(),null);graphics.dispose();var encoded=new ByteArrayOutputStream();ImageIO.write(inputImage,"png",encoded);var inference=detector.detect(r.getString("model"),r.getString("label"),Base64.getEncoder().encodeToString(encoded.toByteArray()));var offset=new JSONArray(new double[]{region.x/(double)image.getWidth(),region.y/(double)image.getHeight(),region.width/(double)image.getWidth(),region.height/(double)image.getHeight()});for(Object raw:inference.getJSONArray("objects")){var o=(JSONObject)raw;var b=o.getJSONArray("box");var mapped=new JSONArray(new double[]{(region.x+b.getDouble(0)*region.width)/image.getWidth(),(region.y+b.getDouble(1)*region.height)/image.getHeight(),(region.x+b.getDouble(2)*region.width)/image.getWidth(),(region.y+b.getDouble(3)*region.height)/image.getHeight()});boolean duplicate=false;for(Object prior:objects)if(PixelTracker.iou(PixelTracker.Box.from(((JSONObject)prior).getJSONArray("box")),PixelTracker.Box.from(mapped))>.7)duplicate=true;if(!duplicate&&objects.length()<6)objects.put(new JSONObject().put("label",o.getString("label")).put("box",mapped));}regions.put(new JSONObject().put("proposal",offset).put("cropSha256",hash(encoded.toByteArray())).put("inferenceWidth",inputImage.getWidth()).put("inferenceHeight",inputImage.getHeight()).put("inference",inference));}result=new JSONObject().put("objects",objects).put("memoryUsed",false).put("regions",regions).put("proposalMethod","Generic flat-border foreground components; full-image fallback when the border is not stable").put("authority","model-estimated categories and boxes from actual proposed pixel regions, not semantic ground truth or personal identity");}
        else if(mode.equals("appearance")){var l=lesson(r.getString("lessonId"));var t=new PixelTracker("candidate",l.getString("label"),PixelTracker.learned(l),PixelTracker.Box.from(l.getJSONArray("box")),false);var m=t.match(PixelTracker.working(image),true);if(m.score()>=.78&&m.anchorScore()>=.65)objects.put(new JSONObject().put("label",l.getString("label")).put("box",m.box().json()));result=new JSONObject().put("objects",objects).put("lessonId",l.getString("id")).put("lessonVersion",l.getInt("version")).put("matchScore",m.score()).put("authority","learned local appearance match; not general category training or personal identity");}
        else {objects.put(new JSONObject().put("label",f.getJSONObject("source").getString("label")).put("box",new JSONArray(new double[]{0,0,1,1})));result=new JSONObject().put("objects",objects).put("authority","page-stated DOM label and actual element geometry, not visual recognition");}
        synchronized(this){var live=runs.get(id);if(!live.getString("status").equals("detecting"))return;if(objects.isEmpty()){live.put("detection",result);persist();throw new IllegalStateException("No requested visual object was found; no tracker or skill promoted");}var seeds=new JSONArray();int i=0;for(Object raw:objects){var o=(JSONObject)raw;String objectId=UUID.nameUUIDFromBytes((id+":"+i++).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();var box=PixelTracker.Box.from(o.getJSONArray("box"));trackers.put(objectId,Tracking024Evaluation.tracker(r.optString("trackerProfile",TrackingEvaluation.BASELINE),objectId,o.getString("label"),image,box));seeds.put(new JSONObject(o.toString()).put("id",objectId));}live.put("detection",result).put("seeds",seeds).put("status","tracking").put("trackingStartedAt",System.currentTimeMillis()).put("reason","Source-qualified detection recorded; waiting for fresh browser frames");persist();}
    }catch(Exception error){synchronized(this){var r=runs.get(id);if(r!=null&&!r.getString("status").equals("cancelled")){r.put("status","interrupted").put("reason",String.valueOf(error.getMessage()));active="";try{persist();}catch(Exception e){System.err.println(e);}}}}}
    public synchronized JSONObject sample(String id,int sequence,String frameId) throws Exception {
        var r=runs.get(id);if(r==null||!r.getString("status").equals("tracking"))throw new IllegalStateException("Perception task is not tracking");if(sequence<1)throw new IllegalArgumentException("Positive sample sequence required");if(sequence<=r.getInt("lastSequence")){var prior=r.getJSONArray("samples").getJSONObject(sequence-1);if(sequence<1||!prior.getString("frameId").equals(frameId))throw new IllegalStateException("Captured sequence already has another source");return copy(prior);}if(sequence!=r.getInt("lastSequence")+1||sequence>120)throw new IllegalStateException("Perception sequence changed or exceeds 120 frames");var f=frame(frameId);if(!binding(f).similar(r.getJSONObject("binding")))throw new IllegalStateException("Browser navigation, media source or selected element changed; rebind explicitly");if(r.getInt("lastSequence")>0&&f.getJSONObject("source").getDouble("capturedAt")<=r.getJSONObject("latest").getDouble("capturedAt"))throw new IllegalStateException("A new sample needs a strictly newer actual frame");var image=decode(bytes(frameId));var objects=new JSONArray();if(r.getString("mode").equals("dom")){var seed=r.getJSONArray("seeds").getJSONObject(0);objects.put(new JSONObject(seed.toString()).put("label",f.getJSONObject("source").getString("label")).put("status","tracked").put("matchScore",JSONObject.NULL).put("authority","DOM geometry"));}else for(var t:trackers.values()){var o=t.update(image);o.put("authority",r.getString("mode").equals("appearance")||r.getJSONObject("detection").optBoolean("memoryUsed")?"user-taught appearance":"local-model estimate, appearance-tracked");objects.put(o);}
        var sample=new JSONObject().put("sequence",sequence).put("frameId",frameId).put("frameSha256",f.getString("sha256")).put("capturedAt",f.getJSONObject("source").getDouble("capturedAt")).put("source",f.getJSONObject("source")).put("objects",objects);r.getJSONArray("samples").put(sample);r.put("lastSequence",sequence).put("latest",sample);persist();return copy(sample);
    }
    static JSONObject metrics(JSONObject r){var samples=r.getJSONArray("samples");int tracked=0,lost=0,reacquired=0,updates=0;double score=0;for(Object raw:samples)for(Object value:((JSONObject)raw).getJSONArray("objects")){var o=(JSONObject)value;boolean visible=Set.of("tracked","reacquired").contains(o.getString("status"));if(visible){tracked++;if(!o.isNull("matchScore"))score+=o.getDouble("matchScore");}else{lost++;if(!o.isNull("box"))throw new IllegalStateException("Lost object incorrectly has a current visible box");}if(o.getString("status").equals("reacquired"))reacquired++;updates=Math.max(updates,o.optInt("appearanceUpdates"));}double fraction=tracked/(double)Math.max(1,tracked+lost);return new JSONObject().put("passed",samples.length()>=4&&tracked>0&&fraction>=.65).put("frames",samples.length()).put("trackedObservations",tracked).put("lostObservations",lost).put("reacquisitions",reacquired).put("trackedFraction",fraction).put("meanMatchScore",r.getString("mode").equals("dom")?JSONObject.NULL:score/Math.max(1,tracked)).put("appearanceUpdates",updates).put("semanticGroundTruthVerified",false).put("mode",r.getString("mode"));}
    public synchronized JSONObject finish(String id) throws Exception {var r=runs.get(id);if(r==null)throw new IllegalArgumentException("Unknown perception run");if(r.getString("status").equals("completed"))return copy(r);if(!r.getString("status").equals("tracking"))throw new IllegalStateException("Cannot complete an inactive tracker");r.put("metrics",metrics(r)).put("status","completed").put("completedAt",Instant.now().toString());active="";trackers.clear();persist();return copy(r);}
    public synchronized JSONObject cancel(String id) throws Exception {var r=runs.get(id);if(r==null)return new JSONObject();if(Set.of("detecting","tracking").contains(r.getString("status"))){r.put("status","cancelled").put("reason","Owned browser observation stopped; no failed skill promoted");active="";trackers.clear();detector.cancel();persist();}return copy(r);}
    public JSONObject verify(String id) throws Exception {var r=run(id);if(!r.getString("status").equals("completed")||!metrics(r).similar(r.getJSONObject("metrics")))throw new IllegalStateException("Perception outcome differs from recorded samples");int sequence=0;double previous=-1;for(Object raw:r.getJSONArray("samples")){var sample=(JSONObject)raw;var f=frame(sample.getString("frameId"));bytes(f.getString("id"));if(sample.getInt("sequence")!=++sequence||!f.getString("sha256").equals(sample.getString("frameSha256"))||!binding(f).similar(r.getJSONObject("binding"))||sample.getDouble("capturedAt")<=previous||!sample.getJSONObject("source").similar(f.getJSONObject("source")))throw new IllegalStateException("Perception source, clock, sequence or hash changed");previous=sample.getDouble("capturedAt");}return r;}
    @Override public void close(){trackingLab.close();synchronized(this){closed=true;detector.cancel();}worker.shutdownNow();}
}
